using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Unity.Collections;
[InitializeOnLoad]public static class FinalPNGMarkingCorrection{
const string ScenePath="Assets/Editor/DayNightBackups/Gangstar Final Env.unity",RootPrefab="Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab",Out="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas";
static FinalPNGMarkingCorrection(){EditorApplication.update+=Poll;}
static void Poll(){if(!File.Exists("FinalPNGMarkingCorrection.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;var mode=File.ReadAllText("FinalPNGMarkingCorrection.request").Trim();File.Delete("FinalPNGMarkingCorrection.request");if(mode=="preview"){JunctionPreview();return;}Run();}
static void Photo(Scene scene,Vector3 p,Vector3 target,string name){typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,p,target,name});}
static void JunctionPreview(){var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");foreach(var name in new[]{"polySurface904","polySurface918","polySurface920","polySurface539","polySurface965"}){var f=root.GetComponentsInChildren<MeshFilter>(true).Single(v=>v.name==name);var b=f.GetComponent<Renderer>().bounds;Photo(scene,b.center+Vector3.up*48,b.center,"Corrected-Junction-"+name);}}
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath(ScenePath);var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var fs=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.GetComponent<MeshRenderer>()&&f.GetComponent<MeshRenderer>().sharedMaterial&&f.GetComponent<MeshRenderer>().sharedMaterial.name=="City PNG Markings").ToArray();string stamp=DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");EditorSceneManager.SaveScene(scene,"FinalEnvironmentRoadBackup/BeforeLaneCorrections-"+stamp+".unity",true);File.Copy(RootPrefab,"FinalEnvironmentRoadBackup/BeforeLaneCorrections-"+stamp+".prefab");var changes=new Dictionary<MeshFilter,Mesh>();int corrected=0;
foreach(var f in fs){var source=f.sharedMesh;Vector3[] p;Vector4[] uv;int[] ids;using(var all=MeshUtility.AcquireReadOnlyMeshData(source)){var md=all[0];using(var arr=new NativeArray<Vector3>(md.vertexCount,Allocator.Temp)){md.GetVertices(arr);p=arr.ToArray();}using(var arr=new NativeArray<Vector4>(md.vertexCount,Allocator.Temp)){md.GetUVs(3,arr);uv=arr.ToArray();}using(var arr=new NativeArray<int>(md.GetSubMesh(0).indexCount,Allocator.Temp)){md.GetIndices(arr,0);ids=arr.ToArray();}}int tile=Mathf.FloorToInt(uv[0].x/32);if(tile>=8&&tile<=12)continue;float orientation=0;for(int k=0;k<ids.Length;k+=3){int a=ids[k],b=ids[k+1],c=ids[k+2];var ab=f.transform.TransformPoint(p[b])-f.transform.TransformPoint(p[a]);var ac=f.transform.TransformPoint(p[c])-f.transform.TransformPoint(p[a]);float dw=ab.x*ac.z-ab.z*ac.x;var ub=uv[b]-uv[a];var uc=uv[c]-uv[a];float dt=ub.x*uc.y-ub.y*uc.x;if(Mathf.Abs(dw)>.001f&&Mathf.Abs(dt)>.00001f){orientation=dw/dt;break;}}if(orientation==0)throw new Exception("Cannot determine mapping orientation: "+f.name);if(orientation<0){for(int i=0;i<uv.Length;i++){uv[i].y=uv[i].w-uv[i].y;uv[i].z=1-uv[i].z;}var mesh=UnityEngine.Object.Instantiate(source);mesh.name="PNG_LaneAligned_"+f.name;mesh.SetUVs(3,uv.ToList());string path=Out+"/Meshes/"+mesh.name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,path);using(var read=MeshUtility.AcquireReadOnlyMeshData(mesh)){using(var arr=new NativeArray<Vector3>(mesh.vertexCount,Allocator.Temp)){read[0].GetVertices(arr);if(!arr.ToArray().SequenceEqual(p))throw new Exception("Geometry changed");}}changes.Add(f,mesh);corrected++;}log.AppendLine(f.name+" tile="+tile+" mirrored="+(orientation<0));}
var prefab=PrefabUtility.LoadPrefabContents(RootPrefab);try{foreach(var item in changes){string path=AnimationUtility.CalculateTransformPath(item.Key.transform,root.transform);var pf=prefab.transform.Find(path).GetComponent<MeshFilter>();pf.sharedMesh=item.Value;}PrefabUtility.SaveAsPrefabAsset(prefab,RootPrefab,out bool ok);if(!ok)throw new Exception("Prefab save failed");}finally{PrefabUtility.UnloadPrefabContents(prefab);}foreach(var item in changes){item.Key.sharedMesh=item.Value;PrefabUtility.RecordPrefabInstancePropertyModifications(item.Key);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");int errors=ShaderUtil.GetShaderMessages(AssetDatabase.LoadAssetAtPath<Shader>(Out+"/Shaders/RoadDetailAtlas.shader")).Count(m=>m.severity.ToString()=="Error");if(errors>0)throw new Exception("Shader errors="+errors);
foreach(var f in fs.Where(f=>f.name=="polySurface809"||f.name=="polySurface539"||f.name=="Continuous underpass roadway")){var b=f.GetComponent<Renderer>().bounds;Photo(scene,b.center+Vector3.up*38,b.center,"Corrected-"+f.name+"-"+f.GetInstanceID());}foreach(var f in fs){using(var all=MeshUtility.AcquireReadOnlyMeshData(f.sharedMesh))using(var arr=new NativeArray<Vector4>(all[0].vertexCount,Allocator.Temp)){all[0].GetUVs(3,arr);if(Mathf.FloorToInt(arr[0].x/32)!=1)continue;var b=f.GetComponent<Renderer>().bounds;Photo(scene,b.center+Vector3.up*45,b.center,"Corrected-Bus-"+f.name);}}
log.AppendLine("SUCCESS: mirrored road mappings corrected="+corrected+"; road renderers="+fs.Length+"; geometry/colliders retained; scene and prefab saved; shader errors=0.");}catch(Exception e){log.AppendLine("FAILED "+e);Debug.LogException(e);}File.WriteAllText("FinalEnvironmentRoadReview/PNGMarkingCorrections.txt",log.ToString());}
}


